const entrada = $input.first().json;

// Localiza o texto retornado pelo nó OpenAI
const resposta =
  entrada.output?.[0]?.content?.[0]?.text
  || entrada.output_text
  || entrada.text
  || entrada.message?.content
  || '';

if (!resposta) {
  throw new Error('A resposta da IA não foi encontrada.');
}

let texto = String(resposta).trim();

// Remove marcações que eventualmente sejam retornadas pela IA
texto = texto
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let pedido;

try {
  pedido = JSON.parse(texto);
} catch (error) {
  throw new Error(
    `A IA não retornou um JSON válido. Erro: ${error.message}`
  );
}

if (!pedido || typeof pedido !== 'object') {
  throw new Error('O conteúdo retornado não representa um pedido válido.');
}

if (!Array.isArray(pedido.itens)) {
  throw new Error('O campo "itens" não foi encontrado ou não é uma lista.');
}

if (pedido.itens.length === 0) {
  throw new Error('Nenhum item foi identificado no pedido.');
}

// Gera um item do n8n para cada produto do pedido
return pedido.itens.map((produto, indice) => ({
  json: {
    numero_pedido: pedido.numero_pedido ?? null,
    cliente: pedido.cliente ?? null,
    data_emissao: pedido.data_emissao ?? null,

    item: produto.item ?? indice + 1,
    codigo_cliente: produto.codigo_cliente ?? null,
    descricao_original: String(
      produto.descricao_original || ''
    ).trim(),

    quantidade: produto.quantidade ?? null,
    unidade: produto.unidade ?? null,
    ncm: produto.ncm ?? null,

    marca: produto.marca ?? null,
    modelo: produto.modelo ?? null,
    produto_base: produto.produto_base ?? null,

    volume: produto.volume ?? null,
    peso: produto.peso ?? null,
    dimensoes: produto.dimensoes ?? null,
    concentracao: produto.concentracao ?? null,
    cor: produto.cor ?? null,
    material: produto.material ?? null,

    quantidade_embalagem:
      produto.quantidade_embalagem ?? null,

    atributos: Array.isArray(produto.atributos)
      ? produto.atributos
      : [],
  },
  pairedItem: {
    item: 0,
  },
}));

function removerAcentos(texto) {
  return String(texto || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalizarTexto(texto) {
  return removerAcentos(texto)
    .toUpperCase()
    .replace(/,/g, '.')
    .replace(/[^A-Z0-9.%/°º²µX\- ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizarUnidadeMedida(unidade) {
  const valor = normalizarTexto(unidade);

  const equivalencias = {
    UN: 'UNIDADE',
    UND: 'UNIDADE',
    UNID: 'UNIDADE',
    UNIDADE: 'UNIDADE',

    CX: 'CAIXA',
    CAIX: 'CAIXA',
    CAIXA: 'CAIXA',

    PC: 'PACOTE',
    PCT: 'PACOTE',
    PAC: 'PACOTE',
    PACOTE: 'PACOTE',

    FD: 'FARDO',
    FARDO: 'FARDO',

    GL: 'GALAO',
    GALA: 'GALAO',
    GALAO: 'GALAO',

    KG: 'QUILOGRAMA',
    QUILOGRAMA: 'QUILOGRAMA',

    LT: 'LITRO',
    L: 'LITRO',
    LITRO: 'LITRO',

    RS: 'RESMA',
    RESMA: 'RESMA'
  };

  return equivalencias[valor] || valor || null;
}

function extrairMedidas(texto) {
  const normalizado = normalizarTexto(texto);

  const medidas = normalizado.match(
    /\d+(?:\.\d+)?\s*(?:ML|L|G|KG|MM|CM|M|UN|V|%)/g
  ) || [];

  return [...new Set(
    medidas.map(medida => medida.replace(/\s+/g, ''))
  )];
}

function normalizarAtributos(atributos) {
  if (!Array.isArray(atributos)) {
    return [];
  }

  return [...new Set(
    atributos
      .map(normalizarTexto)
      .filter(Boolean)
  )];
}

const descricaoOriginal = String(
  $json.descricao_original || ''
).trim();

if (!descricaoOriginal) {
  throw new Error(
    `Descrição vazia no item ${$json.item ?? 'desconhecido'}.`
  );
}

const descricaoNormalizada =
  normalizarTexto(descricaoOriginal);

const produtoBaseNormalizado =
  normalizarTexto($json.produto_base);

const volumeNormalizado =
  normalizarTexto($json.volume);

const pesoNormalizado =
  normalizarTexto($json.peso);

const dimensoesNormalizadas =
  normalizarTexto($json.dimensoes);

const concentracaoNormalizada =
  normalizarTexto($json.concentracao);

const corNormalizada =
  normalizarTexto($json.cor);

const materialNormalizado =
  normalizarTexto($json.material);

const marcaNormalizada =
  normalizarTexto($json.marca);

const modeloNormalizado =
  normalizarTexto($json.modelo);

const atributosNormalizados =
  normalizarAtributos($json.atributos);

const medidasEncontradas = extrairMedidas(
  [
    descricaoOriginal,
    $json.volume,
    $json.peso,
    $json.dimensoes,
    $json.concentracao,
    ...(Array.isArray($json.atributos)
      ? $json.atributos
      : [])
  ].join(' ')
);

return {
  ...$json,

  unidade_normalizada:
    normalizarUnidadeMedida($json.unidade),

  descricao_normalizada:
    descricaoNormalizada,

  produto_base_normalizado:
    produtoBaseNormalizado,

  volume_normalizado:
    volumeNormalizado || null,

  peso_normalizado:
    pesoNormalizado || null,

  dimensoes_normalizadas:
    dimensoesNormalizadas || null,

  concentracao_normalizada:
    concentracaoNormalizada || null,

  cor_normalizada:
    corNormalizada || null,

  material_normalizado:
    materialNormalizado || null,

  marca_normalizada:
    marcaNormalizada || null,

  modelo_normalizado:
    modeloNormalizado || null,

  atributos_normalizados:
    atributosNormalizados,

  medidas_encontradas:
    medidasEncontradas
};

const palavrasIgnoradas = new Set([
  'DE', 'DA', 'DO', 'DAS', 'DOS',
  'PARA', 'COM', 'SEM', 'POR',
  'EM', 'E', 'A', 'O',
  'TIPO', 'MATERIAL', 'COR',
  'CARACTER', 'CARACTERISTICO',
  'FABRICANTE', 'FORNECIMENTO',
  'EMBALAGEM', 'MODELO'
]);

function palavrasValidas(texto) {
  return String(texto || '')
    .split(/\s+/)
    .map(palavra => palavra.trim())
    .filter(palavra =>
      palavra.length >= 2 &&
      !palavrasIgnoradas.has(palavra)
    );
}

function termosUnicos(lista) {
  return [...new Set(
    lista
      .map(valor => String(valor || '').trim())
      .filter(Boolean)
  )];
}

const produtoBase = String(
  $json.produto_base_normalizado || ''
).trim();

const descricao = String(
  $json.descricao_normalizada || ''
).trim();

if (!produtoBase) {
  throw new Error(
    `Produto-base não encontrado no item ${$json.item}.`
  );
}

// Termos principais do nome do produto
const termosProdutoBase = palavrasValidas(produtoBase);

// Características que ajudam a diferenciar produtos parecidos
const termosTecnicos = termosUnicos([
  $json.volume_normalizado,
  $json.peso_normalizado,
  $json.dimensoes_normalizadas,
  $json.concentracao_normalizada,
  $json.cor_normalizada,
  $json.material_normalizado,
  $json.marca_normalizada,
  $json.modelo_normalizado,
  ...(Array.isArray($json.atributos_normalizados)
    ? $json.atributos_normalizados
    : []),
  ...(Array.isArray($json.medidas_encontradas)
    ? $json.medidas_encontradas
    : [])
]);

// Termos usados para recuperação ampla no Oracle
const termosBusca = termosUnicos([
  ...termosProdutoBase,
  ...termosTecnicos
]);

// Limita apenas para evitar uma consulta excessivamente grande.
// Os termos mais importantes continuam vindo primeiro.
const termosLimitados = termosBusca.slice(0, 12);

return {
  ...$json,

  termo_produto_1: termosProdutoBase[0] || '',
  termo_produto_2: termosProdutoBase[1] || '',
  termo_produto_3: termosProdutoBase[2] || '',

  termo_tecnico_1: termosTecnicos[0] || '',
  termo_tecnico_2: termosTecnicos[1] || '',
  termo_tecnico_3: termosTecnicos[2] || '',
  termo_tecnico_4: termosTecnicos[3] || '',
  termo_tecnico_5: termosTecnicos[4] || '',

  termos_busca: termosLimitados,

  texto_busca_completo: termosLimitados.join(' '),

  quantidade_termos_busca: termosLimitados.length
};

// Todos os produtos solicitados antes da consulta ao Oracle
const produtosSolicitados =
  $('Preparar busca no banco').all().map(item => item.json);

// Todas as linhas retornadas pelo Oracle
const linhasOracle = $input.all().map(item => item.json);

// Agrupa os candidatos pelo número do item do pedido
const candidatosPorItem = new Map();

for (const linha of linhasOracle) {
  const numeroItem = Number(linha.ITEM_PEDIDO || 0);

  if (!numeroItem) {
    continue;
  }

  if (!candidatosPorItem.has(numeroItem)) {
    candidatosPorItem.set(numeroItem, []);
  }

  candidatosPorItem.get(numeroItem).push({
    codigo: linha.CODPROD ?? null,
    descricao: String(linha.DESCRICAO || '').trim(),
    similaridade: Number(linha.SIMILARIDADE || 0),
    pontos_termos: Number(linha.PONTOS_TERMOS || 0),
  });
}

// Gera novamente um item para cada produto solicitado,
// inclusive quando o Oracle não encontrou candidatos
return produtosSolicitados.map(produto => {
  const numeroItem = Number(produto.item || 0);

  const candidatos = candidatosPorItem.get(numeroItem) || [];

  // Remove códigos duplicados
  const candidatosUnicos = [
    ...new Map(
      candidatos.map(candidato => [
        String(candidato.codigo),
        candidato,
      ])
    ).values(),
  ];

  // Ordena primeiro pela pontuação dos termos
  // e depois pela similaridade textual
  candidatosUnicos.sort((a, b) => {
    if (b.pontos_termos !== a.pontos_termos) {
      return b.pontos_termos - a.pontos_termos;
    }

    return b.similaridade - a.similaridade;
  });

  // Mantém somente os 10 melhores
  const melhoresCandidatos = candidatosUnicos.slice(0, 50);

  return {
    json: {
      numero_pedido: produto.numero_pedido ?? null,
      cliente: produto.cliente ?? null,
      data_emissao: produto.data_emissao ?? null,

      item: produto.item ?? null,
      codigo_cliente: produto.codigo_cliente ?? null,
      descricao_original: produto.descricao_original ?? '',
      quantidade: produto.quantidade ?? null,
      unidade: produto.unidade ?? null,
      unidade_normalizada:
        produto.unidade_normalizada ?? null,
      ncm: produto.ncm ?? null,

      produto_base:
        produto.produto_base ?? null,
      produto_base_normalizado:
        produto.produto_base_normalizado ?? null,

      volume: produto.volume ?? null,
      peso: produto.peso ?? null,
      dimensoes: produto.dimensoes ?? null,
      concentracao: produto.concentracao ?? null,
      cor: produto.cor ?? null,
      material: produto.material ?? null,
      marca: produto.marca ?? null,
      modelo: produto.modelo ?? null,

      quantidade_embalagem:
        produto.quantidade_embalagem ?? null,

      atributos: produto.atributos ?? [],
      medidas_encontradas:
        produto.medidas_encontradas ?? [],

      quantidade_candidatos:
        melhoresCandidatos.length,

      candidatos: melhoresCandidatos,

      nenhum_candidato:
        melhoresCandidatos.length === 0,
    },
  };
});

function normalizar(texto) {
  return String(texto || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/,/g, '.')
    .replace(/\s+/g, ' ')
    .trim();
}

function numero(valor) {
  return Number(
    String(valor || '')
      .replace(',', '.')
      .trim()
  );
}

function valoresIguaisComTolerancia(
  valorA,
  valorB,
  tolerancia = 0.001
) {
  return (
    Math.abs(Number(valorA) - Number(valorB)) <=
    tolerancia
  );
}

function possuiIntersecaoNumerica(listaA, listaB) {
  return listaA.some(valorA =>
    listaB.some(valorB =>
      valoresIguaisComTolerancia(valorA, valorB)
    )
  );
}

function valoresUnicos(lista) {
  return [
    ...new Set(
      lista.filter(valor => Number.isFinite(valor))
    ),
  ];
}

/**
 * Converte:
 *
 * volume      → mililitros
 * peso        → gramas
 * comprimento → milímetros
 */
function extrairMedidas(texto) {
  let valor = normalizar(texto);

  /*
   * Padroniza unidades que aparecem grudadas no número:
   *
   * 400GRS → 400 G
   * 500GR  → 500 G
   * 05KG   → 05 KG
   * 5LT    → 5 L
   * 500ML  → 500 ML
   */
  valor = valor
    .replace(/(\d)\s*LITROS?\b/g, '$1 L ')
    .replace(/(\d)\s*LTS?\b/g, '$1 L ')
    .replace(/(\d)\s*LT\b/g, '$1 L ')

    .replace(/(\d)\s*KILOS?\b/g, '$1 KG ')
    .replace(/(\d)\s*QUILOS?\b/g, '$1 KG ')
    .replace(/(\d)\s*KGS?\b/g, '$1 KG ')

    .replace(/(\d)\s*GRAMAS?\b/g, '$1 G ')
    .replace(/(\d)\s*GRS?\b/g, '$1 G ')
    .replace(/(\d)\s*GR\b/g, '$1 G ')

    .replace(/(\d)\s*MLS?\b/g, '$1 ML ')

    .replace(
      /(\d)\s*CENTIMETROS?\b/g,
      '$1 CM '
    )
    .replace(
      /(\d)\s*MILIMETROS?\b/g,
      '$1 MM '
    )
    .replace(/(\d)\s*METROS?\b/g, '$1 M ')

    .replace(/\s+/g, ' ')
    .trim();

  const resultado = {
    volumes_ml: [],
    pesos_g: [],
    comprimentos_mm: [],
    percentuais: [],
    voltagens: [],
    quantidades_un: [],
  };

  function adicionar(lista, valorNumerico) {
    if (Number.isFinite(valorNumerico)) {
      lista.push(valorNumerico);
    }
  }

  /*
   * Dimensões compostas:
   *
   * 100X125X25MM
   * 22X20.7CM
   * 35X17CM
   * 0.20X200M
   */
  const regexDimensoes =
    /(\d+(?:\.\d+)?(?:\s*X\s*\d+(?:\.\d+)?)+)\s*(MM|CM|M)\b/g;

  let match;

  while ((match = regexDimensoes.exec(valor)) !== null) {
    const partes = match[1]
      .split(/\s*X\s*/)
      .map(Number)
      .filter(Number.isFinite);

    const unidade = match[2];

    const fator =
      unidade === 'MM'
        ? 1
        : unidade === 'CM'
          ? 10
          : 1000;

    for (const parte of partes) {
      adicionar(
        resultado.comprimentos_mm,
        parte * fator
      );
    }
  }

  /*
   * Remove as dimensões compostas para evitar
   * contabilização duplicada.
   */
  const textoSemDimensoes = valor.replace(
    regexDimensoes,
    ' '
  );

  const regexMedidas =
    /(\d+(?:\.\d+)?)\s*(ML|L|KG|G|MM|CM|M|%|V|UN)\b/g;

  while (
    (match = regexMedidas.exec(textoSemDimensoes)) !==
    null
  ) {
    const quantidade = numero(match[1]);
    const unidade = match[2];

    if (!Number.isFinite(quantidade)) {
      continue;
    }

    switch (unidade) {
      case 'ML':
        adicionar(
          resultado.volumes_ml,
          quantidade
        );
        break;

      case 'L':
        adicionar(
          resultado.volumes_ml,
          quantidade * 1000
        );
        break;

      case 'G':
        adicionar(
          resultado.pesos_g,
          quantidade
        );
        break;

      case 'KG':
        adicionar(
          resultado.pesos_g,
          quantidade * 1000
        );
        break;

      case 'MM':
        adicionar(
          resultado.comprimentos_mm,
          quantidade
        );
        break;

      case 'CM':
        adicionar(
          resultado.comprimentos_mm,
          quantidade * 10
        );
        break;

      case 'M':
        adicionar(
          resultado.comprimentos_mm,
          quantidade * 1000
        );
        break;

      case '%':
        adicionar(
          resultado.percentuais,
          quantidade
        );
        break;

      case 'V':
        adicionar(
          resultado.voltagens,
          quantidade
        );
        break;

      case 'UN':
        adicionar(
          resultado.quantidades_un,
          quantidade
        );
        break;
    }
  }

  resultado.volumes_ml =
    valoresUnicos(resultado.volumes_ml);

  resultado.pesos_g =
    valoresUnicos(resultado.pesos_g);

  resultado.comprimentos_mm =
    valoresUnicos(resultado.comprimentos_mm);

  resultado.percentuais =
    valoresUnicos(resultado.percentuais);

  resultado.voltagens =
    valoresUnicos(resultado.voltagens);

  resultado.quantidades_un =
    valoresUnicos(resultado.quantidades_un);

  return resultado;
}

function verificarMedidaObrigatoria(
  nome,
  valoresSolicitados,
  valoresCandidato,
  conflitos,
  naoConfirmados
) {
  if (valoresSolicitados.length === 0) {
    return;
  }

  if (valoresCandidato.length === 0) {
    naoConfirmados.push(
      `${nome} não identificado na descrição do candidato`
    );
    return;
  }

  if (
    !possuiIntersecaoNumerica(
      valoresSolicitados,
      valoresCandidato
    )
  ) {
    conflitos.push(
      `${nome} incompatível: solicitado ${valoresSolicitados.join(', ')}; candidato ${valoresCandidato.join(', ')}`
    );
  }
}

function detectarTipoPilha(texto) {
  const valor = normalizar(texto);

  /*
   * AAA precisa ser verificado antes de AA.
   * Também aceita descrições como AAAC/2.
   */
  if (
    /(^|[^A-Z])AAA([^A-Z]|$)/.test(valor) ||
    valor.includes('PAL.AAA') ||
    valor.includes('PAL AAA') ||
    valor.includes('AAA C/')
  ) {
    return 'AAA';
  }

  if (
    /(^|[^A-Z])AA([^A-Z]|$)/.test(valor) ||
    valor.includes('PEQ.AA') ||
    valor.includes('PEQ AA') ||
    valor.includes('AA C/')
  ) {
    return 'AA';
  }

  return null;
}

function detectarFolha(texto) {
  const valor = normalizar(texto);

  if (
    valor.includes('FOLHA DUPLA') ||
    valor.includes('FL DUPLA')
  ) {
    return 'DUPLA';
  }

  if (
    valor.includes('FOLHA SIMPLES') ||
    valor.includes('FL SIMPLES')
  ) {
    return 'SIMPLES';
  }

  return null;
}

function detectarPff(texto) {
  const valor = normalizar(texto);

  const match =
    valor.match(/\bPFF\s*([123])\b/) ||
    valor.match(/\bPFF-([123])\b/);

  return match ? `PFF${match[1]}` : null;
}

function detectarTamanhoGrampo(texto) {
  const valor = normalizar(texto);

  const match = valor.match(
    /\b(\d{1,2}\/\d)\b/
  );

  return match ? match[1] : null;
}

function detectarQuantidadeEmbalagem(texto) {
  const valor = normalizar(texto);

  /*
   * Somente padrões que indicam quantidade física
   * de unidades, folhas, rolos ou peças.
   *
   * Não interpreta:
   * C/500 GRS
   * C/1000 ML
   * C/5 KG
   */
  const padroes = [
    /\bC\/\s*(\d+)\s*UN\b/,
    /\bC\/(\d+)\s*UN\b/,
    /\bCX\s*C\/\s*(\d+)\s*UN\b/,
    /\bPACOTE\s*C\/\s*(\d+)\s*UN\b/,
    /\bPC\s*C\/\s*(\d+)\s*UN\b/,

    /\bC\/\s*(\d+)\s*FLS?\b/,
    /\bC\/\s*(\d+)\s*FL\b/,
    /\b(\d+)\s*FLS?\b/,
    /\b(\d+)\s*FL\b/,

    /\bC\/\s*(\d+)\s*RLS?\b/,
    /\bC\/\s*(\d+)\s*ROLOS?\b/,

    /\b(\d+)\s*UN\b/,
  ];

  for (const padrao of padroes) {
    const match = valor.match(padrao);

    if (match) {
      const quantidade = Number(match[1]);

      return Number.isFinite(quantidade)
        ? quantidade
        : null;
    }
  }

  return null;
}

function detectarDigitosCalculadora(texto) {
  const valor = normalizar(texto);

  const match =
    valor.match(/\b(\d{1,2})\s*DIG\b/) ||
    valor.match(/\b(\d{1,2})\s*DIGITOS?\b/);

  return match ? Number(match[1]) : null;
}

function detectarTamanhoRegua(texto) {
  const valor = normalizar(texto);

  if (!valor.includes('REGUA')) {
    return null;
  }

  const match = valor.match(
    /\b(\d+(?:\.\d+)?)\s*CM\b/
  );

  return match ? Number(match[1]) : null;
}

function detectarProdutoPortaPapel(texto) {
  const valor = normalizar(texto);

  return (
    valor.includes('PORTA PAPEL') ||
    valor.includes('DISPENSER PAPEL') ||
    valor.includes('DISPENSADOR PAPEL')
  );
}

function detectarMarcadorCd(texto) {
  const valor = normalizar(texto);

  return (
    valor.includes('MARCADOR CD') ||
    valor.includes('MARCADOR DVD') ||
    valor.includes('CD/DVD') ||
    valor.includes('CD / DVD')
  );
}

function detectarMarcaTexto(texto) {
  const valor = normalizar(texto);

  return (
    valor.includes('MARCA TEXTO') ||
    valor.includes('MARCA-TEXTO')
  );
}

function detectarLapis(texto) {
  const valor = normalizar(texto);

  return /\bLAPIS\b/.test(valor);
}

function detectarLapiseira(texto) {
  const valor = normalizar(texto);

  return /\bLAPISEIRA\b/.test(valor);
}

function detectarColaBastao(texto) {
  const valor = normalizar(texto);

  return (
    valor.includes('COLA') &&
    valor.includes('BASTAO')
  );
}

function detectarPapelEscolar(texto) {
  const valor = normalizar(texto);

  return (
    valor.includes('PAPEL ESCOLAR') ||
    valor.includes('PAPEL COLORIDO')
  );
}

const descricaoSolicitada = normalizar(
  $json.descricao_original
);

const medidasSolicitadas = extrairMedidas(
  [
    $json.descricao_original,
    $json.volume,
    $json.peso,
    $json.dimensoes,
    $json.concentracao,
    ...(Array.isArray($json.atributos)
      ? $json.atributos
      : []),
  ].join(' ')
);

const tipoPilhaSolicitado =
  detectarTipoPilha(descricaoSolicitada);

const folhaSolicitada =
  detectarFolha(descricaoSolicitada);

const pffSolicitado =
  detectarPff(descricaoSolicitada);

const grampoSolicitado =
  detectarTamanhoGrampo(descricaoSolicitada);

const quantidadeEmbalagemSolicitada =
  Number($json.quantidade_embalagem || 0) ||
  detectarQuantidadeEmbalagem(
    descricaoSolicitada
  );

const digitosCalculadoraSolicitada =
  detectarDigitosCalculadora(
    descricaoSolicitada
  );

const tamanhoReguaSolicitado =
  detectarTamanhoRegua(descricaoSolicitada);

const solicitadoEhPortaPapel =
  detectarProdutoPortaPapel(
    descricaoSolicitada
  );

const solicitadoEhMarcaTexto =
  detectarMarcaTexto(descricaoSolicitada);

const solicitadoEhMarcadorCd =
  detectarMarcadorCd(descricaoSolicitada);

const solicitadoEhLapis =
  detectarLapis(descricaoSolicitada);

const solicitadoEhLapiseira =
  detectarLapiseira(descricaoSolicitada);

const solicitadoEhColaBastao =
  detectarColaBastao(descricaoSolicitada);

const solicitadoEhPapelEscolar =
  detectarPapelEscolar(
    descricaoSolicitada
  );

const quantidadeSolicitada = Number(
  $json.quantidade || 0
);

const candidatos = Array.isArray(
  $json.candidatos
)
  ? $json.candidatos
  : [];

const candidatosValidados = candidatos.map(
  candidato => {
    const descricaoCandidato = normalizar(
      candidato.descricao
    );

    const medidasCandidato =
      extrairMedidas(descricaoCandidato);

    const conflitos = [];
    const atributosNaoConfirmados = [];

    verificarMedidaObrigatoria(
      'volume',
      medidasSolicitadas.volumes_ml,
      medidasCandidato.volumes_ml,
      conflitos,
      atributosNaoConfirmados
    );

    verificarMedidaObrigatoria(
      'peso',
      medidasSolicitadas.pesos_g,
      medidasCandidato.pesos_g,
      conflitos,
      atributosNaoConfirmados
    );

    verificarMedidaObrigatoria(
      'dimensão',
      medidasSolicitadas.comprimentos_mm,
      medidasCandidato.comprimentos_mm,
      conflitos,
      atributosNaoConfirmados
    );

    verificarMedidaObrigatoria(
      'concentração',
      medidasSolicitadas.percentuais,
      medidasCandidato.percentuais,
      conflitos,
      atributosNaoConfirmados
    );

    verificarMedidaObrigatoria(
      'voltagem',
      medidasSolicitadas.voltagens,
      medidasCandidato.voltagens,
      conflitos,
      atributosNaoConfirmados
    );

    const tipoPilhaCandidato =
      detectarTipoPilha(descricaoCandidato);

    if (
      tipoPilhaSolicitado &&
      tipoPilhaCandidato &&
      tipoPilhaSolicitado !== tipoPilhaCandidato
    ) {
      conflitos.push(
        `tipo de pilha incompatível: solicitado ${tipoPilhaSolicitado}; candidato ${tipoPilhaCandidato}`
      );
    }

    if (
      tipoPilhaSolicitado &&
      !tipoPilhaCandidato
    ) {
      atributosNaoConfirmados.push(
        `tipo de pilha ${tipoPilhaSolicitado} não confirmado`
      );
    }

    const folhaCandidato =
      detectarFolha(descricaoCandidato);

    if (
      folhaSolicitada &&
      folhaCandidato &&
      folhaSolicitada !== folhaCandidato
    ) {
      conflitos.push(
        `tipo de folha incompatível: solicitado ${folhaSolicitada}; candidato ${folhaCandidato}`
      );
    }

    if (
      folhaSolicitada &&
      !folhaCandidato
    ) {
      atributosNaoConfirmados.push(
        `tipo de folha ${folhaSolicitada} não confirmado`
      );
    }

    const pffCandidato =
      detectarPff(descricaoCandidato);

    if (
      pffSolicitado &&
      pffCandidato &&
      pffSolicitado !== pffCandidato
    ) {
      conflitos.push(
        `classe incompatível: solicitado ${pffSolicitado}; candidato ${pffCandidato}`
      );
    }

    if (
      pffSolicitado &&
      !pffCandidato
    ) {
      atributosNaoConfirmados.push(
        `classe ${pffSolicitado} não confirmada`
      );
    }

    const grampoCandidato =
      detectarTamanhoGrampo(
        descricaoCandidato
      );

    if (
      grampoSolicitado &&
      grampoCandidato &&
      grampoSolicitado !== grampoCandidato
    ) {
      conflitos.push(
        `tamanho incompatível: solicitado ${grampoSolicitado}; candidato ${grampoCandidato}`
      );
    }

    if (
      grampoSolicitado &&
      !grampoCandidato
    ) {
      atributosNaoConfirmados.push(
        `tamanho ${grampoSolicitado} não confirmado`
      );
    }

    const quantidadeEmbalagemCandidato =
      detectarQuantidadeEmbalagem(
        descricaoCandidato
      );

    /*
     * Embalagem diferente não elimina o produto.
     * Apenas registra a diferença para cálculo posterior.
     */
    if (
      quantidadeEmbalagemSolicitada &&
      quantidadeEmbalagemCandidato &&
      quantidadeEmbalagemSolicitada !==
        quantidadeEmbalagemCandidato
    ) {
      atributosNaoConfirmados.push(
        `embalagem diferente: solicitado ${quantidadeEmbalagemSolicitada} unidade(s); candidato contém ${quantidadeEmbalagemCandidato} unidade(s)`
      );
    }

    if (
      quantidadeEmbalagemSolicitada &&
      !quantidadeEmbalagemCandidato
    ) {
      atributosNaoConfirmados.push(
        `quantidade por embalagem ${quantidadeEmbalagemSolicitada} não confirmada`
      );
    }

    const quantidadePacotesNecessarios =
      quantidadeEmbalagemCandidato &&
      quantidadeSolicitada > 0
        ? Math.ceil(
            quantidadeSolicitada /
              quantidadeEmbalagemCandidato
          )
        : null;

    const quantidadeTotalFornecida =
      quantidadePacotesNecessarios &&
      quantidadeEmbalagemCandidato
        ? quantidadePacotesNecessarios *
          quantidadeEmbalagemCandidato
        : null;

    const quantidadeExcedente =
      quantidadeTotalFornecida !== null &&
      quantidadeSolicitada > 0
        ? quantidadeTotalFornecida -
          quantidadeSolicitada
        : null;

    const digitosCalculadoraCandidato =
      detectarDigitosCalculadora(
        descricaoCandidato
      );

    if (
      digitosCalculadoraSolicitada &&
      digitosCalculadoraCandidato &&
      digitosCalculadoraSolicitada !==
        digitosCalculadoraCandidato
    ) {
      conflitos.push(
        `quantidade de dígitos incompatível: solicitado ${digitosCalculadoraSolicitada}; candidato ${digitosCalculadoraCandidato}`
      );
    }

    if (
      digitosCalculadoraSolicitada &&
      !digitosCalculadoraCandidato
    ) {
      atributosNaoConfirmados.push(
        `${digitosCalculadoraSolicitada} dígitos não confirmados`
      );
    }

    const tamanhoReguaCandidato =
      detectarTamanhoRegua(
        descricaoCandidato
      );

    if (
      tamanhoReguaSolicitado &&
      tamanhoReguaCandidato &&
      tamanhoReguaSolicitado !==
        tamanhoReguaCandidato
    ) {
      conflitos.push(
        `tamanho da régua incompatível: solicitado ${tamanhoReguaSolicitado}CM; candidato ${tamanhoReguaCandidato}CM`
      );
    }

    const candidatoEhPortaPapel =
      detectarProdutoPortaPapel(
        descricaoCandidato
      );

    if (
      !solicitadoEhPortaPapel &&
      candidatoEhPortaPapel &&
      (
        descricaoSolicitada.includes(
          'PAPEL HIGIENICO'
        ) ||
        descricaoSolicitada.includes(
          'PAPEL TOALHA'
        )
      )
    ) {
      conflitos.push(
        'finalidade incompatível: solicitado papel; candidato é porta-papel'
      );
    }

    const candidatoEhMarcaTexto =
      detectarMarcaTexto(
        descricaoCandidato
      );

    const candidatoEhMarcadorCd =
      detectarMarcadorCd(
        descricaoCandidato
      );

    if (
      solicitadoEhMarcaTexto &&
      candidatoEhMarcadorCd
    ) {
      conflitos.push(
        'finalidade incompatível: solicitado marca-texto; candidato é marcador para CD/DVD'
      );
    }

    if (
      solicitadoEhMarcadorCd &&
      candidatoEhMarcaTexto
    ) {
      conflitos.push(
        'finalidade incompatível: solicitado marcador para CD/DVD; candidato é marca-texto'
      );
    }

    const candidatoEhLapis =
      detectarLapis(descricaoCandidato);

    const candidatoEhLapiseira =
      detectarLapiseira(
        descricaoCandidato
      );

    if (
      solicitadoEhLapis &&
      candidatoEhLapiseira
    ) {
      conflitos.push(
        'tipo incompatível: solicitado lápis; candidato é lapiseira'
      );
    }

    if (
      solicitadoEhLapiseira &&
      candidatoEhLapis
    ) {
      conflitos.push(
        'tipo incompatível: solicitado lapiseira; candidato é lápis'
      );
    }

    const candidatoEhColaBastao =
      detectarColaBastao(
        descricaoCandidato
      );

    const candidatoEhPapelEscolar =
      detectarPapelEscolar(
        descricaoCandidato
      );

    if (
      solicitadoEhColaBastao &&
      candidatoEhPapelEscolar
    ) {
      conflitos.push(
        'tipo incompatível: solicitado cola bastão; candidato é papel escolar'
      );
    }

    if (
      solicitadoEhPapelEscolar &&
      candidatoEhColaBastao
    ) {
      conflitos.push(
        'tipo incompatível: solicitado papel escolar; candidato é cola bastão'
      );
    }

    return {
      ...candidato,

      quantidade_embalagem_candidato:
        quantidadeEmbalagemCandidato,

      quantidade_pacotes_necessarios:
        quantidadePacotesNecessarios,

      quantidade_total_fornecida:
        quantidadeTotalFornecida,

      quantidade_excedente:
        quantidadeExcedente,

      compativel:
        conflitos.length === 0,

      possui_conflito:
        conflitos.length > 0,

      conflitos,

      atributos_nao_confirmados:
        atributosNaoConfirmados,

      quantidade_conflitos:
        conflitos.length,

      quantidade_nao_confirmados:
        atributosNaoConfirmados.length,
    };
  }
);

const candidatosCompativeis =
  candidatosValidados
    .filter(candidato => candidato.compativel)
    .sort((a, b) => {
      /*
       * Primeiro, candidatos com menos atributos
       * não confirmados.
       */
      if (
        a.quantidade_nao_confirmados !==
        b.quantidade_nao_confirmados
      ) {
        return (
          a.quantidade_nao_confirmados -
          b.quantidade_nao_confirmados
        );
      }

      /*
       * Depois, menor excedente de embalagem.
       */
      const excedenteA =
        a.quantidade_excedente ?? 999999;

      const excedenteB =
        b.quantidade_excedente ?? 999999;

      if (excedenteA !== excedenteB) {
        return excedenteA - excedenteB;
      }

      if (
        b.pontos_termos !==
        a.pontos_termos
      ) {
        return (
          b.pontos_termos -
          a.pontos_termos
        );
      }

      return (
        b.similaridade -
        a.similaridade
      );
    });

const candidatosRejeitados =
  candidatosValidados.filter(
    candidato => !candidato.compativel
  );

return {
  ...$json,

  candidatos_originais:
    candidatos.length,

  candidatos_compativeis:
    candidatosCompativeis,

  candidatos_rejeitados:
    candidatosRejeitados,

  quantidade_compativeis:
    candidatosCompativeis.length,

  quantidade_rejeitados:
    candidatosRejeitados.length,

  nenhum_candidato_compativel:
    candidatosCompativeis.length === 0,
};

function norm(v) {
  return String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function lista(v) {
  if (!Array.isArray(v)) return [];

  return [
    ...new Set(
      v
        .map(x => String(x ?? '').trim())
        .filter(Boolean)
    ),
  ];
}

function inteiro(v, min = 0, max = 100) {
  const n = Number(v);

  return Number.isFinite(n)
    ? Math.min(
        max,
        Math.max(min, Math.round(n))
      )
    : min;
}

function textoIa(entrada) {
  if (
    typeof entrada?.output_text === 'string'
  ) {
    return entrada.output_text.trim();
  }

  if (typeof entrada?.text === 'string') {
    return entrada.text.trim();
  }

  if (
    typeof entrada?.message?.content === 'string'
  ) {
    return entrada.message.content.trim();
  }

  for (const bloco of entrada?.output || []) {
    for (const conteudo of bloco?.content || []) {
      if (
        typeof conteudo?.text === 'string' &&
        conteudo.text.trim()
      ) {
        return conteudo.text.trim();
      }
    }
  }

  return '';
}

function limparJson(v) {
  return String(v || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function conflitoExplicito(motivo) {
  let v = norm(motivo)
    .replace(
      /SEM INCOMPATIBILIDADE EXPLICITA/g,
      ''
    )
    .replace(
      /SEM INCOMPATIBILIDADE/g,
      ''
    )
    .replace(
      /NAO HA INCOMPATIBILIDADE EXPLICITA/g,
      ''
    )
    .replace(
      /NAO HA INCOMPATIBILIDADE/g,
      ''
    );

  return [
    /\bCONFLIT/,
    /\bINCOMPATIVEL/,
    /NAO CORRESPONDE/,
    /NAO ATENDE/,
    /FINALIDADE DIFERENTE/,
    /CATEGORIA DIFERENTE/,
    /PRODUTO ACESSORIO/,
    /TIPO DIFERENTE/,
    /TAMANHO DIFERENTE/,
    /MEDIDA DIFERENTE/,
  ].some(r => r.test(v));
}

function resumo(c, posicao) {
  if (!c) return null;

  return {
    codigo:
      String(c.codigo),

    descricao:
      String(c.descricao || '').trim(),

    posicao_previa:
      posicao,

    pontos_termos:
      Number(c.pontos_termos || 0),

    similaridade:
      Number(c.similaridade || 0),

    atributos_nao_confirmados_deterministicos:
      lista(c.atributos_nao_confirmados),

    quantidade_embalagem_candidato:
      c.quantidade_embalagem_candidato ?? null,

    quantidade_pacotes_necessarios:
      c.quantidade_pacotes_necessarios ?? null,

    quantidade_total_fornecida:
      c.quantidade_total_fornecida ?? null,

    quantidade_excedente:
      c.quantidade_excedente ?? null,
  };
}

/*
 * Extrai e interpreta a resposta do nó OpenAI.
 */
const bruto = textoIa($json);

let decisao = null;
let erroParse = null;

try {
  decisao = JSON.parse(
    limparJson(bruto)
  );
} catch (e) {
  erroParse = bruto
    ? `JSON inválido retornado pela IA: ${e.message}`
    : 'Resposta textual da IA não encontrada.';
}

/*
 * Recupera o item que foi enviado para a IA.
 */
let origem = null;

try {
  origem =
    $('Preparar candidatos para IA').item.json;
} catch (e) {
  // Usa o fallback abaixo.
}

/*
 * Fallback para quando o pareamento automático
 * entre os itens não estiver disponível.
 */
if (
  (!origem || !origem.item) &&
  decisao?.item != null
) {
  origem =
    $('Preparar candidatos para IA')
      .all()
      .map(i => i.json)
      .find(i =>
        Number(i.item) ===
        Number(decisao.item)
      ) || null;
}

if (!origem) {
  throw new Error(
    'Item original não encontrado no nó "Preparar candidatos para IA".'
  );
}

const base = {
  numero_pedido:
    origem.numero_pedido ?? null,

  cliente:
    origem.cliente ?? null,

  data_emissao:
    origem.data_emissao ?? null,

  item:
    origem.item ?? null,

  codigo_cliente:
    origem.codigo_cliente ?? null,

  descricao_original:
    origem.descricao_original ?? '',

  quantidade:
    origem.quantidade ?? null,

  unidade:
    origem.unidade ?? null,

  unidade_normalizada:
    origem.unidade_normalizada ?? null,

  ncm:
    origem.ncm ?? null,

  total_candidatos_oracle:
    Number(
      origem.total_candidatos_oracle || 0
    ),

  total_candidatos_para_ia:
    Number(
      origem.total_candidatos_para_ia || 0
    ),
};

/*
 * Não interrompe o workflow caso a IA retorne
 * texto vazio ou JSON inválido.
 */
if (
  erroParse ||
  !decisao ||
  typeof decisao !== 'object'
) {
  return {
    ...base,

    status_ia:
      null,

    status_final:
      'ERRO_IA',

    codigo_produto_selecionado:
      null,

    descricao_produto_selecionado:
      null,

    posicao_previa:
      null,

    confianca_ia:
      0,

    motivo_ia:
      erroParse,

    atributos_confirmados:
      [],

    atributos_nao_confirmados:
      [],

    candidato_selecionado:
      null,

    alternativas:
      [],

    alternativas_descartadas:
      [],

    validacao_ia_ok:
      false,

    status_processamento:
      'ERRO_IA',

    necessita_reprocessar_ia:
      true,

    erros_validacao: [
      erroParse,
    ],

    avisos_validacao:
      [],

    resposta_ia_bruta:
      bruto || null,
  };
}

const erros = [];
const avisos = [];

const permitidos = new Set([
  'APROVADO',
  'REVISAR',
  'SEM_CORRESPONDENCIA',
]);

const statusIa =
  norm(decisao.status);

let confianca =
  inteiro(decisao.confianca);

if (!permitidos.has(statusIa)) {
  erros.push(
    `Status inválido: ${
      decisao.status ?? 'vazio'
    }.`
  );
}

if (
  Number(decisao.item) !==
  Number(origem.item)
) {
  erros.push(
    `Item divergente: origem ${origem.item}; IA ${decisao.item}.`
  );
}

/*
 * Cria um mapa dos únicos códigos que
 * a IA tinha permissão de selecionar.
 */
const candidatos = Array.isArray(
  origem.candidatos_para_ia
)
  ? origem.candidatos_para_ia
  : [];

const mapa = new Map(
  candidatos.map(
    (candidato, indice) => [
      String(candidato.codigo),
      {
        candidato,
        posicao: indice + 1,
      },
    ]
  )
);

let codigo =
  decisao.codigo_selecionado == null
    ? null
    : String(
        decisao.codigo_selecionado
      ).trim();

let selecionado =
  codigo
    ? mapa.get(codigo)
    : null;

/*
 * SEM_CORRESPONDENCIA nunca pode
 * carregar um produto selecionado.
 */
if (
  statusIa === 'SEM_CORRESPONDENCIA'
) {
  if (
    codigo ||
    decisao.descricao_selecionada ||
    decisao.posicao_previa != null
  ) {
    avisos.push(
      'Seleção removida porque o status é SEM_CORRESPONDENCIA.'
    );
  }

  codigo = null;
  selecionado = null;
} else {
  if (!codigo) {
    erros.push(
      'APROVADO/REVISAR sem código selecionado.'
    );
  } else if (!selecionado) {
    erros.push(
      `Código ${codigo} não existe em candidatos_para_ia.`
    );
  }
}

/*
 * A descrição e a posição finais passam a
 * vir do candidato real, e não do texto da IA.
 */
if (selecionado) {
  const descricaoBanco =
    String(
      selecionado.candidato.descricao || ''
    ).trim();

  if (
    String(
      decisao.descricao_selecionada || ''
    ).trim() !== descricaoBanco
  ) {
    avisos.push(
      'Descrição corrigida para o texto exato do banco.'
    );
  }

  if (
    Number(decisao.posicao_previa) !==
    selecionado.posicao
  ) {
    avisos.push(
      `Posição corrigida para ${selecionado.posicao}.`
    );
  }
}

const confirmados =
  lista(decisao.atributos_confirmados);

const naoConfirmados =
  lista([
    ...lista(
      decisao.atributos_nao_confirmados
    ),

    ...lista(
      selecionado
        ?.candidato
        ?.atributos_nao_confirmados
    ),
  ]);

let statusFinal =
  permitidos.has(statusIa)
    ? statusIa
    : 'ERRO_IA';

/*
 * A IA não pode aprovar automaticamente
 * um candidato com baixa confiança ou
 * atributos ainda não confirmados.
 */
if (
  statusFinal === 'APROVADO' &&
  (
    confianca < 90 ||
    naoConfirmados.length > 0
  )
) {
  statusFinal = 'REVISAR';

  avisos.push(
    'APROVADO rebaixado para REVISAR por confiança baixa ou atributos não confirmados.'
  );
}

/*
 * Uma decisão abaixo de 60 não pode manter
 * um produto selecionado.
 */
if (
  statusFinal === 'REVISAR' &&
  confianca < 60
) {
  statusFinal =
    'SEM_CORRESPONDENCIA';

  codigo = null;
  selecionado = null;

  avisos.push(
    'REVISAR rebaixado para SEM_CORRESPONDENCIA por confiança inferior a 60.'
  );
}

if (
  statusFinal ===
  'SEM_CORRESPONDENCIA'
) {
  confianca =
    Math.min(confianca, 59);

  codigo = null;
  selecionado = null;
}

/*
 * Código inventado, status inválido ou item
 * divergente gera ERRO_IA.
 */
if (erros.length > 0) {
  statusFinal =
    'ERRO_IA';

  codigo = null;
  selecionado = null;
}

/*
 * Valida e higieniza as alternativas.
 */
const alternativas = [];
const descartadas = [];
const usados = new Set();

for (
  const alt of (
    Array.isArray(decisao.alternativas)
      ? decisao.alternativas
      : []
  )
) {
  if (alternativas.length >= 2) {
    break;
  }

  const cod =
    alt?.codigo == null
      ? ''
      : String(alt.codigo).trim();

  const motivo =
    String(alt?.motivo || '').trim();

  const reg =
    mapa.get(cod);

  if (!cod || !reg) {
    descartadas.push({
      codigo:
        cod || null,

      descricao:
        alt?.descricao ?? null,

      motivo_descarte:
        'Código não existe em candidatos_para_ia.',
    });

    continue;
  }

  if (
    codigo &&
    cod === codigo
  ) {
    descartadas.push({
      codigo:
        cod,

      descricao:
        reg.candidato.descricao,

      motivo_descarte:
        'Alternativa igual ao selecionado.',
    });

    continue;
  }

  if (usados.has(cod)) {
    continue;
  }

  /*
   * Descarta alternativas cujo próprio motivo
   * admite conflito ou incompatibilidade.
   */
  if (
    conflitoExplicito(motivo)
  ) {
    descartadas.push({
      codigo:
        cod,

      descricao:
        reg.candidato.descricao,

      motivo_descarte:
        'O motivo da IA indica incompatibilidade explícita.',

      motivo_ia:
        motivo,
    });

    continue;
  }

  usados.add(cod);

  alternativas.push({
    ...resumo(
      reg.candidato,
      reg.posicao
    ),

    motivo,
  });
}

if (descartadas.length > 0) {
  avisos.push(
    `${descartadas.length} alternativa(s) descartada(s) por código inválido, duplicidade ou conflito explícito.`
  );
}

const candidatoSelecionado =
  selecionado
    ? resumo(
        selecionado.candidato,
        selecionado.posicao
      )
    : null;

return {
  ...base,

  status_ia:
    statusIa || null,

  status_final:
    statusFinal,

  codigo_produto_selecionado:
    candidatoSelecionado
      ?.codigo ?? null,

  descricao_produto_selecionado:
    candidatoSelecionado
      ?.descricao ?? null,

  posicao_previa:
    candidatoSelecionado
      ?.posicao_previa ?? null,

  confianca_ia:
    confianca,

  motivo_ia:
    String(
      decisao.motivo || ''
    ).trim(),

  atributos_confirmados:
    confirmados,

  atributos_nao_confirmados:
    naoConfirmados,

  candidato_selecionado:
    candidatoSelecionado,

  alternativas,

  alternativas_descartadas:
    descartadas,

  validacao_ia_ok:
    erros.length === 0,

  status_processamento:
    erros.length
      ? 'ERRO_IA'
      : avisos.length
        ? 'VALIDADO_COM_AJUSTES'
        : 'VALIDADO',

  necessita_reprocessar_ia:
    erros.length > 0,

  erros_validacao:
    erros,

  avisos_validacao:
    avisos,

  resposta_ia_bruta:
    bruto,
};

function textoOuNull(valor) {
  const texto = String(valor ?? '').trim();

  return texto || null;
}

function numeroSeguro(valor) {
  const numero = Number(valor);

  return Number.isFinite(numero)
    ? numero
    : 0;
}

function listarAtributosSolicitados(solicitacao) {
  const atributos = [];

  function adicionar(rotulo, valor) {
    const texto = textoOuNull(valor);

    if (texto) {
      atributos.push(`${rotulo}: ${texto}`);
    }
  }

  adicionar(
    'produto',
    solicitacao.produto_base
  );

  adicionar(
    'volume',
    solicitacao.volume
  );

  adicionar(
    'peso',
    solicitacao.peso
  );

  adicionar(
    'dimensões',
    solicitacao.dimensoes
  );

  adicionar(
    'concentração',
    solicitacao.concentracao
  );

  adicionar(
    'cor',
    solicitacao.cor
  );

  adicionar(
    'material',
    solicitacao.material
  );

  adicionar(
    'marca',
    solicitacao.marca
  );

  adicionar(
    'modelo',
    solicitacao.modelo
  );

  if (
    solicitacao.quantidade_embalagem_solicitada !==
      null &&
    solicitacao.quantidade_embalagem_solicitada !==
      undefined
  ) {
    adicionar(
      'quantidade por embalagem',
      solicitacao.quantidade_embalagem_solicitada
    );
  }

  const atributosOriginais =
    Array.isArray(solicitacao.atributos)
      ? solicitacao.atributos
      : [];

  for (const atributo of atributosOriginais) {
    adicionar(
      'atributo',
      atributo
    );
  }

  return [
    ...new Set(atributos),
  ];
}

const solicitacao =
  $json.solicitacao_para_ia &&
  typeof $json.solicitacao_para_ia === 'object'
    ? $json.solicitacao_para_ia
    : {};

const totalOracle =
  numeroSeguro(
    $json.total_candidatos_oracle
  );

const totalRejeitados =
  numeroSeguro(
    $json.total_candidatos_rejeitados
  );

let motivo;

if (totalOracle === 0) {
  motivo =
    'Nenhum produto candidato foi encontrado no banco de dados para este item.';
} else if (
  totalRejeitados >= totalOracle
) {
  motivo =
    `Foram encontrados ${totalOracle} candidato(s), mas todos foram rejeitados pelas validações objetivas de compatibilidade.`;
} else {
  motivo =
    'Nenhum candidato suficientemente compatível permaneceu disponível para avaliação semântica.';
}

return {
  numero_pedido:
    $json.numero_pedido ?? null,

  cliente:
    $json.cliente ?? null,

  data_emissao:
    $json.data_emissao ?? null,

  item:
    $json.item ?? null,

  codigo_cliente:
    $json.codigo_cliente ?? null,

  descricao_original:
    $json.descricao_original ?? '',

  quantidade:
    $json.quantidade ?? null,

  unidade:
    $json.unidade ?? null,

  unidade_normalizada:
    $json.unidade_normalizada ?? null,

  ncm:
    $json.ncm ?? null,

  total_candidatos_oracle:
    totalOracle,

  total_candidatos_rejeitados:
    totalRejeitados,

  total_candidatos_para_ia:
    0,

  status_ia:
    null,

  status_final:
    'SEM_CORRESPONDENCIA',

  codigo_produto_selecionado:
    null,

  descricao_produto_selecionado:
    null,

  posicao_previa:
    null,

  confianca_ia:
    0,

  motivo_ia:
    motivo,

  motivo_final:
    motivo,

  atributos_confirmados:
    [],

  atributos_nao_confirmados:
    listarAtributosSolicitados(
      solicitacao
    ),

  candidato_selecionado:
    null,

  alternativas:
    [],

  alternativas_descartadas:
    [],

  validacao_ia_ok:
    null,

  origem_decisao:
    'REGRA_SEM_CANDIDATO',

  status_processamento:
    'SEM_CANDIDATO_PARA_IA',

  necessita_reprocessar_ia:
    false,

  erros_validacao:
    [],

  avisos_validacao: [
    motivo,
  ],

  resposta_ia_bruta:
    null,
};

function texto(valor) {
  return String(valor ?? '').trim();
}

function listaTexto(valor) {
  if (!Array.isArray(valor)) {
    return '';
  }

  return valor
    .map(item => String(item ?? '').trim())
    .filter(Boolean)
    .join(' | ');
}

function primeiraAlternativa(item) {
  return Array.isArray(item.alternativas) &&
    item.alternativas.length > 0
      ? item.alternativas[0]
      : null;
}

const linhas = $input.all()
  .map(item => item.json)
  .sort((a, b) => Number(a.item || 0) - Number(b.item || 0))
  .map(item => {
    const temSelecionado =
      item.codigo_produto_selecionado &&
      item.descricao_produto_selecionado;

    const alternativa =
      primeiraAlternativa(item);

    const codigoConferencia = temSelecionado
      ? item.codigo_produto_selecionado
      : alternativa?.codigo ?? null;

    const descricaoConferencia = temSelecionado
      ? item.descricao_produto_selecionado
      : alternativa?.descricao ?? null;

    const origemOpcao = temSelecionado
      ? 'CANDIDATO_SELECIONADO_IA'
      : alternativa
        ? 'SEGUNDA_OPCAO_IA'
        : 'SEM_OPCAO';

    return {
      json: {
        pedido: item.numero_pedido ?? '',
        cliente: item.cliente ?? '',
        data_emissao: item.data_emissao ?? '',

        item: item.item ?? '',
        codigo_cliente: item.codigo_cliente ?? '',
        descricao_solicitada_cliente: item.descricao_original ?? '',
        quantidade_solicitada: item.quantidade ?? '',
        unidade_solicitada: item.unidade_normalizada || item.unidade || '',
        ncm: item.ncm ?? '',

        status_ia: item.status_ia ?? '',
        status_final: item.status_final ?? '',
        confianca_ia: item.confianca_ia ?? '',

        codigo_produto_para_conferencia: codigoConferencia ?? '',
        descricao_produto_para_conferencia: descricaoConferencia ?? '',
        origem_opcao_planilha: origemOpcao,

        codigo_selecionado_ia: item.codigo_produto_selecionado ?? '',
        descricao_selecionada_ia: item.descricao_produto_selecionado ?? '',

        codigo_segunda_opcao: alternativa?.codigo ?? '',
        descricao_segunda_opcao: alternativa?.descricao ?? '',
        motivo_segunda_opcao: alternativa?.motivo ?? '',

        motivo_ia: item.motivo_ia ?? '',
        atributos_confirmados: listaTexto(item.atributos_confirmados),
        atributos_nao_confirmados: listaTexto(item.atributos_nao_confirmados),

        validacao_ia_ok: item.validacao_ia_ok ?? '',
        status_processamento: item.status_processamento ?? '',
        avisos_validacao: listaTexto(item.avisos_validacao),
      },
    };
  });

return linhas;
